902:     /// Write the material into a child process's environment block.
903:     ///
904:     /// This is the whole exposed surface of a resolved credential, and it is
905:     /// [`Command::env`] rather than `std::env::set_var` on purpose: the value
906:     /// reaches exactly one child and never becomes visible to this process, to
907:     /// another concurrent resolution, or to anything reading `/proc`'s command
908:     /// line.
909:     pub fn apply(&self, command: &mut Command) {
910:         for (name, value) in &self.entries {
911:             command.env(name.as_str(), value.expose_secret());
912:         }
913:     }

14: /// Credential effects are isolated by immutable Realm and canonical state root.
15: /// A copied Realm database under another root cannot update the original root.
16: #[derive(Clone)]
17: pub struct JiraCredentialScope {
18:     service: String,
19: }
20: 
21: impl JiraCredentialScope {
22:     pub fn at(root: &Path, realm: RealmId) -> Result<Self, JiraError> {
23:         if !root.is_absolute() {
24:             return Err(refused("the credential root must be absolute"));
25:         }
26:         let root = root
27:             .canonicalize()
28:             .map_err(|_| refused("the credential root could not be canonicalized"))?;
29:         if !root.is_dir() {
30:             return Err(refused("the credential root must be a directory"));
31:         }
32:         let root_hash = ContentHash::of(root.as_os_str().as_encoded_bytes());
33:         Ok(Self {
34:             service: format!("kontor-jira:{realm}:{root_hash}"),
35:         })
36:     }
37: 
38:     pub(crate) fn target(&self, alias: &str) -> KeychainTarget {
39:         KeychainTarget::new(self.service.clone(), alias.to_owned())
40:     }
41: }

