295: /// Serve one Realm until the process is asked to stop.
296: async fn serve(state_root: PathBuf, port: u16, origins: Vec<String>) -> std::process::ExitCode {
297:     let mut config = DaemonConfig::at(state_root).with_port(port);
298:     if !origins.is_empty() {
299:         config.allowed_origins = origins;
300:     }
301:     // The fleet comes from the state root, so the shipped daemon's session routes
302:     // are backed by the adapters this Realm is configured with. A Realm with no
303:     // `runtimes.json` composes an empty fleet and says so below rather than
304:     // pretending to have one.
305:     let daemon = match Daemon::start_configured(config) {
306:         Ok(daemon) => daemon,
307:         Err(error) => {
308:             error!(detail = %error, "kontor could not start");
309:             return std::process::ExitCode::FAILURE;
310:         }
